#!/usr/bin/env python3
"""Apply a locally verified source implementation delta; never rewrite drift."""
import base64
import gzip
import hashlib
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PATCH = """"""

def main():
    patch = gzip.decompress(base64.b64decode(PATCH))
    if hashlib.sha256(patch).hexdigest() != 'b3f837a4879cfdbf6d9167f5e7b9b7c19b763266c761386736606dcdb601ebc1':
        raise SystemExit('proof patch integrity mismatch')
    allowed = {'crates/fln-elab/src/source.rs', 'crates/fln-elab/src/source/tactics.rs', 'crates/fln-elab/tests/source_proofs.rs', 'crates/fln-parse/src/lib.rs', 'crates/fln-parse/src/proofs.rs'}
    for line in patch.decode().splitlines():
        if line.startswith('+++ b/') and line[6:] not in allowed:
            raise SystemExit('unexpected patch target')
    subprocess.run(['git', 'apply', '--check', '-'], input=patch, cwd=ROOT, check=True)
    subprocess.run(['git', 'apply', '-'], input=patch, cwd=ROOT, check=True)

if __name__ == '__main__':
    main()
